#!/usr/bin/env Rscript
# Output is a R GenomicRanges object containing exons for all trascripts generated by the script utils/get_transcript_and_promoters.R with the following format saved as TSV file
#                     seqnames   ranges        strand |   TXID        TXNAME           ENSEMBL
#                     <Rle>      <IRanges>     <Rle>  |   <integer>   <character>      <character>
#  NM_001005484.2     chr1       65019-65518      +   |   1           NM_001005484.2   ENSG00000186092

library(txdbmaker) # Create TxDb from UCSC gene tracks
library(rtracklayer) # Enables importing bedfiles etc
library(GenomicRanges) # For interesction of regions
library(BSgenome)
library(biomaRt)

rep_transcripts <- readRDS("./input/representative_transcripts.rds")

# Collect refseqselect/mane transcripts from UCSC #####
refseq_select <- makeTxDbFromUCSC(genome = "hg38", tablename = "ncbiRefSeqSelect") # This is RefSeq Select and MANE

# Remove non chromosomal scaffolds -> this works. (https://bioc.r-universe.dev/GenomicFeatures/doc/GenomicFeatures.html)
seqlevels(refseq_select) <- grep(seqlevels(refseq_select), invert = TRUE, pattern = "_", value = TRUE)

# Get the all exons per gene. But note, some exons are linked to multiple transcript IDs, so we need to fix that...
rep_exons_raw <- exons(refseq_select, columns = c("TXNAME", "TXID"))
txnames_list <- rep_exons_raw$TXNAME # Note
no_replicated_exons <- lapply(FUN = length, X = txnames_list) |> unlist()
rep_exons <- rep_exons_raw
mcols(rep_exons) <- NULL
rep_exons <- rep(rep_exons, times = no_replicated_exons)
mcols(rep_exons) <- data.frame(TXNAME = unlist(txnames_list))
rep_exons$TXNAME <- gsub(rep_exons$TXNAME, pattern = "\\..*", replacement = "")

# Keep only exons of those transcripts that match the TXID as well as the seqnames (this is because duplicated transcripts from the pseudoautosomal regions)
exons_to_keep <- `%in%`(paste0(seqnames(rep_exons),"-",rep_exons$TXNAME), paste0(seqnames(rep_transcripts),"-",rep_transcripts$TXNAME))

# Now add ENSEMBL IDs and TXIDs
mcols(rep_exons) <- mcols(rep_exons) |>
  as.data.frame() |>
  left_join(as.data.frame(mcols(rep_transcripts)), by = join_by("TXNAME"))

# Write to file
write.table(rep_exons, "./input/representative_exons.tsv", row.names = FALSE, quote = FALSE, sep = "\t")
